-- Тест 1: Смоленск в Отечественной войне 1812 года
INSERT INTO tests(id, title, topic, description, questions, time_limit) VALUES
    ('11111111-1111-1111-1111-111111111111',
     'Смоленск в Отечественной войне 1812 года',
     'Смоленск 1812',
     'Проверьте свои знания о Смоленском сражении и роли города в войне с Наполеоном',
     '[
       {"id":"q1","text":"Когда началось Смоленское сражение 1812 года?","options":["4–6 августа 1812","14–17 июня 1812","26 августа 1812","12 октября 1812"],"correct":0,"points":1},
       {"id":"q2","text":"Кто командовал русскими войсками, оборонявшими Смоленск?","options":["М. И. Кутузов","П. И. Багратион и М. Б. Барклай-де-Толли","А. В. Суворов","М. Д. Скобелев"],"correct":1,"points":1},
       {"id":"q3","text":"Какой корпус первым принял бой у Смоленска 4 августа?","options":["Корпус Раевского","Корпус Дохтурова","Корпус Тучкова","Корпус Платова"],"correct":0,"points":2},
       {"id":"q4","text":"Кто командовал французской армией под Смоленском?","options":["Мюрат","Наполеон Бонапарт","Ней","Даву"],"correct":1,"points":1},
       {"id":"q5","text":"Какая икона считалась покровительницей защитников Смоленска?","options":["Казанская","Владимирская","Смоленская „Одигитрия“","Тихвинская"],"correct":2,"points":2},
       {"id":"q6","text":"Что произошло со Смоленском после отхода русской армии?","options":["Был восстановлен","Сильно пострадал от пожара и разрушений","Остался нетронутым","Был сдан без боя"],"correct":1,"points":1},
       {"id":"q7","text":"Какое значение имело Смоленское сражение?","options":["Задержало Наполеона и позволило русским отступить в порядке","Полностью разгромило французов","Не имело значения","Привело к капитуляции Наполеона"],"correct":0,"points":2},
       {"id":"q8","text":"Когда французы оставили Смоленск при отступлении?","options":["Ноябрь 1812","Сентябрь 1812","Январь 1813","Декабрь 1812"],"correct":0,"points":1},
       {"id":"q9","text":"Какой памятник посвящён защитникам Смоленска 1812 года?","options":["Памятник Глинке","Памятник с орлами (1913)","Курган Бессмертия","Памятник Кутузову"],"correct":1,"points":2},
       {"id":"q10","text":"Кто из русских генералов погиб в боях за Смоленск?","options":["Н. Н. Раевский","А. А. Скалон","М. И. Платов","Д. В. Давыдов"],"correct":1,"points":2}
     ]'::jsonb,
     20);

-- Тест 2: Никифор Мурзакевич — историк Смоленска
INSERT INTO tests(id, title, topic, description, questions, time_limit) VALUES
    ('22222222-2222-2222-2222-222222222222',
     'Никифор Мурзакевич — историк Смоленска',
     'Мурзакевич',
     'Тест о жизни и трудах первого историка Смоленска',
     '[
       {"id":"q1","text":"В каком году родился Никифор Адрианович Мурзакевич?","options":["1769","1755","1780","1795"],"correct":0,"points":1},
       {"id":"q2","text":"Какое главное произведение написал Мурзакевич?","options":["„Смоленский летописец“","„История губернского города Смоленска“","„Путь к вере“","„Записки о Смоленщине“"],"correct":1,"points":2},
       {"id":"q3","text":"В каком году впервые была издана „История…Смоленска“?","options":["1804","1812","1820","1798"],"correct":0,"points":2},
       {"id":"q4","text":"Кем по духовному званию был Мурзакевич?","options":["Монахом","Священником (протоиереем)","Епископом","Дьяконом"],"correct":1,"points":1},
       {"id":"q5","text":"При каком храме Смоленска служил Мурзакевич?","options":["Успенский собор","Одигитриевская церковь","Церковь Иоанна Богослова","Вознесенский монастырь"],"correct":2,"points":2},
       {"id":"q6","text":"Что делал Мурзакевич во время оккупации Смоленска в 1812 году?","options":["Эвакуировался","Остался в городе, спасая святыни и летописи","Вступил в ополчение","Уехал в Москву"],"correct":1,"points":2},
       {"id":"q7","text":"Какой жанр преобладает в трудах Мурзакевича?","options":["Краеведческо-исторический","Философский","Поэтический","Драматический"],"correct":0,"points":1},
       {"id":"q8","text":"Год смерти Мурзакевича?","options":["1834","1840","1825","1812"],"correct":0,"points":1},
       {"id":"q9","text":"Почему Мурзакевича называют „отцом смоленской истории“?","options":["Он был первым князем","Он первый систематизировал историю Смоленска по документам","Он построил крепость","Он основал музей"],"correct":1,"points":2},
       {"id":"q10","text":"Какие источники использовал Мурзакевич?","options":["Только устные рассказы","Летописи, грамоты, архивные документы","Только иностранные книги","Только личные воспоминания"],"correct":1,"points":2}
     ]'::jsonb,
     20);

-- Тест 3: Смоленская крепостная стена
INSERT INTO tests(id, title, topic, description, questions, time_limit) VALUES
    ('33333333-3333-3333-3333-333333333333',
     'Смоленская крепостная стена',
     'Крепостная стена',
     'Проверьте знания о выдающемся памятнике русского оборонного зодчества',
     '[
       {"id":"q1","text":"Кто был зодчим Смоленской крепостной стены?","options":["Аристотель Фиораванти","Фёдор Конь","Барма и Постник","Осип Старцев"],"correct":1,"points":1},
       {"id":"q2","text":"В какие годы велось строительство стены?","options":["1595–1602","1550–1560","1620–1630","1500–1510"],"correct":0,"points":2},
       {"id":"q3","text":"При каком царе была возведена стена?","options":["Иван Грозный","Фёдор Иоаннович и Борис Годунов","Алексей Михайлович","Пётр I"],"correct":1,"points":2},
       {"id":"q4","text":"Какова была первоначальная длина стены?","options":["около 6,5 км","около 2 км","около 15 км","около 10 км"],"correct":0,"points":1},
       {"id":"q5","text":"Сколько башен было изначально?","options":["17","38","50","24"],"correct":1,"points":2},
       {"id":"q6","text":"Как назвал крепостную стену Борис Годунов?","options":["„Ожерелье всея Руси“","„Щит земли русской“","„Крепость веры“","„Стена державы“"],"correct":0,"points":2},
       {"id":"q7","text":"Какое событие серьёзно разрушило стену в начале XVII века?","options":["Польская осада 1609–1611","Наполеоновское нашествие","Великая Отечественная война","Пожар 1812 года"],"correct":0,"points":1},
       {"id":"q8","text":"Какая башня стены самая известная?","options":["Громовая","Веселуха (Лучинская)","Орёл","Все перечисленные"],"correct":3,"points":2},
       {"id":"q9","text":"Сколько башен сохранилось до наших дней?","options":["17","9","25","30"],"correct":0,"points":2},
       {"id":"q10","text":"Какова высота стены в среднем?","options":["5–6 метров","10–12 метров","13–19 метров","25 метров"],"correct":2,"points":2}
     ]'::jsonb,
     25);